using System;

class Losowanie
{
    private const int N = 10;
    private int[] tab = new int[N + 1];
    private static readonly Random rnd = new Random();

    public void Wypelnij()
    {
        for (int i = 0; i < N; i++)
            tab[i] = rnd.Next(1, 101);   // górna granica wyłączna
    }

    public void Wypisz()
    {
        for (int i = 0; i < N; i++)
            Console.Write(tab[i] + (i < N - 1 ? ", " : "\n"));
    }

    public int Szukaj(int x)
    {
        tab[N] = x;
        int i = 0;
        while (tab[i] != x) i++;
        return i < N ? i : -1;
    }

    public int IleParzystych()
    {
        int ile = 0;
        for (int i = 0; i < N; i++)
            if (tab[i] % 2 == 0) ile++;
        return ile;
    }
}

class Program
{
    static void Main()
    {
        var los = new Losowanie();
        los.Wypelnij();
        los.Wypisz();

        Console.Write("Podaj liczbę do wyszukania: ");
        int x = int.Parse(Console.ReadLine());
        int poz = los.Szukaj(x);
        Console.WriteLine(poz != -1
            ? $"Liczba {x} jest na pozycji {poz}"
            : $"Nie znaleziono liczby {x}");

        Console.WriteLine($"Liczb parzystych: {los.IleParzystych()}");
    }
}

