import random


class Losowanie:
    N = 10

    def __init__(self):
        self.__tab = [0] * (Losowanie.N + 1)

    def wypelnij(self):
        for i in range(Losowanie.N):
            self.__tab[i] = random.randint(1, 100)   # oba końce włącznie

    def wypisz(self):
        print(", ".join(str(x) for x in self.__tab[:Losowanie.N]))

    def szukaj(self, x):
        self.__tab[Losowanie.N] = x      # wartownik
        i = 0
        while self.__tab[i] != x:
            i += 1
        return i if i < Losowanie.N else -1

    def ile_parzystych(self):
        ile = 0
        for i in range(Losowanie.N):
            if self.__tab[i] % 2 == 0:
                ile += 1
        return ile


if __name__ == "__main__":
    los = Losowanie()
    los.wypelnij()
    los.wypisz()
    x = int(input("Podaj liczbę do wyszukania: "))
    poz = los.szukaj(x)
    if poz != -1:
        print(f"Liczba {x} jest na pozycji {poz}")
    else:
        print(f"Nie znaleziono liczby {x}")
    print(f"Liczb parzystych: {los.ile_parzystych()}")

