import { useState } from 'react';

export default function App() {
  const [imie, setImie] = useState('');
  const [wiek, setWiek] = useState('');
  const [gatunek, setGatunek] = useState('pies');
  const [regulamin, setRegulamin] = useState(false);
  const [komunikat, setKomunikat] = useState('');

  function zatwierdz() {
    if (!regulamin) {
      setKomunikat('Zaakceptuj regulamin');
    } else if (Number(wiek) < 18) {
      setKomunikat('Musisz być pełnoletni');
    } else {
      setKomunikat(`Dziękujemy, ${imie}! Skontaktujemy się w sprawie adopcji: ${gatunek}`);
    }
  }

  return (
    <main>
      <h1>Adoptuj pupila</h1>

      <label htmlFor="imie">Imię:</label>
      <input type="text" id="imie" value={imie} onChange={(e) => setImie(e.target.value)} /><br />

      <label htmlFor="wiek">Wiek:</label>
      <input type="number" id="wiek" value={wiek} onChange={(e) => setWiek(e.target.value)} /><br />

      <label htmlFor="gatunek">Gatunek:</label>
      <select id="gatunek" value={gatunek} onChange={(e) => setGatunek(e.target.value)}>
        <option value="pies">pies</option>
        <option value="kot">kot</option>
        <option value="królik">królik</option>
      </select><br />

      <input type="checkbox" id="regulamin" checked={regulamin} onChange={(e) => setRegulamin(e.target.checked)} />
      <label htmlFor="regulamin">Akceptuję regulamin</label><br />

      <button type="button" id="zatwierdz" onClick={zatwierdz}>Zatwierdź</button>
      <p id="komunikat">{komunikat}</p>
    </main>
  );
}

