package pl.inf04.adopcja;

import javafx.fxml.FXML;
import javafx.scene.control.CheckBox;
import javafx.scene.control.ComboBox;
import javafx.scene.control.Label;
import javafx.scene.control.TextField;

public class MainController {
    @FXML private TextField txtImie;
    @FXML private TextField txtWiek;
    @FXML private ComboBox<String> cmbGatunek;
    @FXML private CheckBox chkRegulamin;
    @FXML private Label lblKomunikat;

    @FXML
    private void initialize() {
        cmbGatunek.getItems().addAll("pies", "kot", "królik");
        cmbGatunek.getSelectionModel().selectFirst();
    }

    @FXML
    private void onZatwierdz() {
        String imie = txtImie.getText().trim();
        int wiek;
        try {
            wiek = Integer.parseInt(txtWiek.getText().trim());
        } catch (NumberFormatException e) {
            wiek = -1;
        }

        if (!chkRegulamin.isSelected()) {
            lblKomunikat.setText("Zaakceptuj regulamin");
        } else if (wiek < 18) {
            lblKomunikat.setText("Musisz być pełnoletni");
        } else {
            lblKomunikat.setText("Dziękujemy, " + imie + "! Skontaktujemy się w sprawie adopcji: " + cmbGatunek.getValue());
        }
    }
}

