package pl.inf04.adopcja;

import android.os.Bundle;
import android.widget.ArrayAdapter;
import android.widget.Button;
import android.widget.CheckBox;
import android.widget.EditText;
import android.widget.Spinner;
import android.widget.TextView;
import androidx.appcompat.app.AppCompatActivity;

public class MainActivity extends AppCompatActivity {

    @Override
    protected void onCreate(Bundle savedInstanceState) {
        super.onCreate(savedInstanceState);
        setContentView(R.layout.activity_main);

        EditText etImie = findViewById(R.id.etImie);
        EditText etWiek = findViewById(R.id.etWiek);
        Spinner spGatunek = findViewById(R.id.spGatunek);
        CheckBox cbRegulamin = findViewById(R.id.cbRegulamin);
        Button btnZatwierdz = findViewById(R.id.btnZatwierdz);
        TextView tvKomunikat = findViewById(R.id.tvKomunikat);

        ArrayAdapter<String> adapter = new ArrayAdapter<>(this,
                android.R.layout.simple_spinner_dropdown_item,
                new String[]{"pies", "kot", "królik"});
        spGatunek.setAdapter(adapter);

        btnZatwierdz.setOnClickListener(v -> {
            String imie = etImie.getText().toString().trim();
            int wiek;
            try {
                wiek = Integer.parseInt(etWiek.getText().toString().trim());
            } catch (NumberFormatException e) {
                wiek = -1;
            }

            if (!cbRegulamin.isChecked()) {
                tvKomunikat.setText("Zaakceptuj regulamin");
            } else if (wiek < 18) {
                tvKomunikat.setText("Musisz być pełnoletni");
            } else {
                tvKomunikat.setText("Dziękujemy, " + imie + "! Skontaktujemy się w sprawie adopcji: "
                        + spGatunek.getSelectedItem().toString());
            }
        });
    }
}

