#include <iostream>
#include <vector>
#include <iomanip>
using namespace std;

class Uczen {
private:
    string imie, nazwisko;
    vector<int> oceny;
public:
    static int liczbaUczniow;

    Uczen(string imie, string nazwisko) : imie(imie), nazwisko(nazwisko) {
        liczbaUczniow++;
    }

    bool dodajOcene(int ocena) {
        if (ocena < 1 || ocena > 6) return false;
        oceny.push_back(ocena);
        return true;
    }

    double srednia() {
        if (oceny.empty()) return 0;
        int suma = 0;
        for (int o : oceny) suma += o;
        return (double)suma / oceny.size();   // rzutowanie!
    }

    bool czyPromocja() {
        if (oceny.empty()) return false;
        for (int o : oceny)
            if (o == 1) return false;
        return true;
    }

    void wypisz() {
        cout << imie << " " << nazwisko << ", średnia: "
             << fixed << setprecision(2) << srednia() << endl;
    }
};

