document.getElementById('licz').addEventListener('click', () => {
    const tekst = document.getElementById('oceny').value;
    const wynik = document.getElementById('wynik');
    const status = document.getElementById('status');

    const oceny = tekst.split(',').map(s => s.trim());
    const poprawne = tekst.trim() !== '' &&
        oceny.every(s => /^[1-6]$/.test(s));

    if (!poprawne) {
        wynik.textContent = 'Niepoprawne dane';
        status.textContent = '';
        return;
    }

    const liczby = oceny.map(Number);
    const suma = liczby.reduce((a, b) => a + b, 0);
    wynik.textContent = 'Średnia: ' + (suma / liczby.length).toFixed(2);

    const promocja = !liczby.includes(1);
    status.textContent = promocja ? 'Promocja' : 'Brak promocji';
    status.style.color = promocja ? 'green' : 'red';
});

