import { useState } from 'react';

export default function App() {
  const [oceny, setOceny] = useState('');
  const [wynik, setWynik] = useState('');
  const [status, setStatus] = useState('');

  function licz() {
    const czesci = oceny.split(',').map((s) => s.trim());
    const poprawne = oceny.trim() !== '' && czesci.every((s) => /^[1-6]$/.test(s));
    if (!poprawne) {
      setWynik('Niepoprawne dane');
      setStatus('');
      return;
    }
    const liczby = czesci.map(Number);
    const suma = liczby.reduce((a, b) => a + b, 0);
    setWynik('Średnia: ' + (suma / liczby.length).toFixed(2));
    setStatus(liczby.includes(1) ? 'Brak promocji' : 'Promocja');
  }

  return (
    <main>
      <h1>Kalkulator średniej</h1>
      <label htmlFor="oceny">Oceny:</label>
      <input type="text" id="oceny" placeholder="np. 5,4,6" value={oceny} onChange={(e) => setOceny(e.target.value)} />
      <button type="button" id="licz" onClick={licz}>Oblicz</button>
      <p id="wynik">{wynik}</p>
      <p id="status" style={{ color: status === 'Promocja' ? 'green' : 'red' }}>{status}</p>
    </main>
  );
}

