    @FXML private Label lblWynik;
    @FXML private Label lblStatus;

    @FXML
    private void onLicz() {
        String[] czesci = txtOceny.getText().split(",");
        int suma = 0;
        boolean jedynka = false;

        for (String c : czesci) {
            String s = c.trim();
            if (!s.matches("[1-6]")) {
                lblWynik.setText("Niepoprawne dane");
                lblStatus.setText("");
