            int ocena = Integer.parseInt(s);
            suma += ocena;
            if (ocena == 1) jedynka = true;
        }

        double srednia = (double) suma / czesci.length;
        lblWynik.setText(String.format(Locale.US, "Średnia: %.2f", srednia));
        lblStatus.setText(jedynka ? "Brak promocji" : "Promocja");
        lblStatus.setTextFill(jedynka ? Color.RED : Color.GREEN);
    }
}

