    {
        Console.Write("Podaj tekst: ");
        string tekst = Console.ReadLine();
        Console.Write("Podaj klucz: ");
        int klucz = int.Parse(Console.ReadLine());

        var s = new Szyfrator(klucz);
        string zaszyfrowany = s.Szyfruj(tekst);
        Console.WriteLine($"Zaszyfrowany: {zaszyfrowany}");
        Console.WriteLine($"Odszyfrowany: {s.Deszyfruj(zaszyfrowany)}");
    }
}

