class Szyfrator:
    def __init__(self, klucz):
        self.__klucz = klucz % 26          # w Pythonie % zawsze daje wynik >= 0

    @staticmethod
    def __przesun(c, k):
        if 'a' <= c <= 'z':
            return chr(ord('a') + (ord(c) - ord('a') + k) % 26)
        if 'A' <= c <= 'Z':
            return chr(ord('A') + (ord(c) - ord('A') + k) % 26)
        return c

    def __przetworz(self, tekst, k):
        return "".join(Szyfrator.__przesun(c, k) for c in tekst)

    def szyfruj(self, tekst):
        return self.__przetworz(tekst, self.__klucz)

    def deszyfruj(self, tekst):
        return self.__przetworz(tekst, 26 - self.__klucz)


if __name__ == "__main__":
    tekst = input("Podaj tekst: ")
    klucz = int(input("Podaj klucz: "))
