const MALE = 'abcdefghijklmnopqrstuvwxyz';
const DUZE = 'ABCDEFGHIJKLMNOPQRSTUVWXYZ';
const CYFRY = '0123456789';
const ZNAKI = '!@#$%&*';

function losowyZnak(pula) {
    return pula[Math.floor(Math.random() * pula.length)];
}

function przetasuj(tab) {
    for (let i = tab.length - 1; i > 0; i--) {
        const j = Math.floor(Math.random() * (i + 1));
        [tab[i], tab[j]] = [tab[j], tab[i]];
    }
    return tab;
}

function generujHaslo(dlugosc, opcje) {
    let pula = MALE;
    const wymagane = [losowyZnak(MALE)];
    if (opcje.duze) { pula += DUZE; wymagane.push(losowyZnak(DUZE)); }
    if (opcje.cyfry) { pula += CYFRY; wymagane.push(losowyZnak(CYFRY)); }
    if (opcje.znaki) { pula += ZNAKI; wymagane.push(losowyZnak(ZNAKI)); }

    const znaki = [...wymagane];
    while (znaki.length < dlugosc) znaki.push(losowyZnak(pula));
    return przetasuj(znaki).join('');
}

document.getElementById('generuj').addEventListener('click', () => {
    const dlugosc = Number(document.getElementById('dlugosc').value);
    const wynik = document.getElementById('haslo');

    if (!Number.isInteger(dlugosc) || dlugosc < 4 || dlugosc > 32) {
        wynik.textContent = 'Długość musi być z zakresu 4–32';
        return;
    }

