import { useState } from 'react';

const MALE = 'abcdefghijklmnopqrstuvwxyz';
const DUZE = 'ABCDEFGHIJKLMNOPQRSTUVWXYZ';
const CYFRY = '0123456789';
const ZNAKI = '!@#$%&*';

const losowyZnak = (pula) => pula[Math.floor(Math.random() * pula.length)];

function przetasuj(tab) {
  for (let i = tab.length - 1; i > 0; i--) {
    const j = Math.floor(Math.random() * (i + 1));
    [tab[i], tab[j]] = [tab[j], tab[i]];
  }
  return tab;
}

export default function App() {
  const [dlugosc, setDlugosc] = useState('12');
  const [duze, setDuze] = useState(false);
  const [cyfry, setCyfry] = useState(false);
  const [znaki, setZnaki] = useState(false);
  const [haslo, setHaslo] = useState('');

  function generuj() {
    const n = Number(dlugosc);
    if (!Number.isInteger(n) || n < 4 || n > 32) {
      setHaslo('Długość musi być z zakresu 4–32');
      return;
    }
    let pula = MALE;
    const wynik = [losowyZnak(MALE)];
    if (duze) { pula += DUZE; wynik.push(losowyZnak(DUZE)); }
    if (cyfry) { pula += CYFRY; wynik.push(losowyZnak(CYFRY)); }
    if (znaki) { pula += ZNAKI; wynik.push(losowyZnak(ZNAKI)); }
    while (wynik.length < n) wynik.push(losowyZnak(pula));
    setHaslo(przetasuj(wynik).join(''));
  }

  return (
    <main>
      <h1>Generator haseł</h1>
      <label htmlFor="dlugosc">Długość:</label>
      <input type="number" id="dlugosc" min="4" max="32" value={dlugosc} onChange={(e) => setDlugosc(e.target.value)} /><br />
      <input type="checkbox" id="duze" checked={duze} onChange={(e) => setDuze(e.target.checked)} />
      <label htmlFor="duze">Wielkie litery</label><br />
      <input type="checkbox" id="cyfry" checked={cyfry} onChange={(e) => setCyfry(e.target.checked)} />
      <label htmlFor="cyfry">Cyfry</label><br />
      <input type="checkbox" id="znaki" checked={znaki} onChange={(e) => setZnaki(e.target.checked)} />
      <label htmlFor="znaki">Znaki specjalne</label><br />
      <button type="button" id="generuj" onClick={generuj}>Generuj</button>
      <p>Hasło: <output id="haslo">{haslo}</output></p>
    </main>
  );
}

