})
export class AppComponent {
  dlugosc: number = 12;
  duze: boolean = false;
  cyfry: boolean = false;
  znaki: boolean = false;
  haslo: string = '';

  private readonly MALE = 'abcdefghijklmnopqrstuvwxyz';
  private readonly DUZE = 'ABCDEFGHIJKLMNOPQRSTUVWXYZ';
  private readonly CYFRY = '0123456789';
  private readonly ZNAKI = '!@#$%&*';

  private losowyZnak(pula: string): string {
    return pula[Math.floor(Math.random() * pula.length)];
  }

  generuj(): void {
    const n = Number(this.dlugosc);
    if (!Number.isInteger(n) || n < 4 || n > 32) {
      this.haslo = 'Długość musi być z zakresu 4–32';
      return;
    }
    let pula = this.MALE;
    const wynik: string[] = [this.losowyZnak(this.MALE)];
    if (this.duze) { pula += this.DUZE; wynik.push(this.losowyZnak(this.DUZE)); }
    if (this.cyfry) { pula += this.CYFRY; wynik.push(this.losowyZnak(this.CYFRY)); }
    if (this.znaki) { pula += this.ZNAKI; wynik.push(this.losowyZnak(this.ZNAKI)); }
    while (wynik.length < n) wynik.push(this.losowyZnak(pula));

    for (let i = wynik.length - 1; i > 0; i--) {
      const j = Math.floor(Math.random() * (i + 1));
      [wynik[i], wynik[j]] = [wynik[j], wynik[i]];
    }
    this.haslo = wynik.join('');
  }
}

