package pl.inf04.hasla;

import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import java.util.Random;
import javafx.fxml.FXML;
import javafx.scene.control.CheckBox;
import javafx.scene.control.Label;
import javafx.scene.control.TextField;

public class MainController {
    @FXML private TextField txtDlugosc;
    @FXML private CheckBox chkDuze;
    @FXML private CheckBox chkCyfry;
    @FXML private CheckBox chkZnaki;
    @FXML private Label lblHaslo;

    private static final String MALE = "abcdefghijklmnopqrstuvwxyz";
    private static final String DUZE = "ABCDEFGHIJKLMNOPQRSTUVWXYZ";
    private static final String CYFRY = "0123456789";
    private static final String ZNAKI = "!@#$%&*";
    private final Random rnd = new Random();

    private char losowyZnak(String pula) {
        return pula.charAt(rnd.nextInt(pula.length()));
    }

    @FXML
    private void onGeneruj() {

        String tekst = txtDlugosc.getText().trim();
        int dlugosc;
        try {
            dlugosc = Integer.parseInt(tekst);
        } catch (NumberFormatException e) {
            dlugosc = -1;
        }
        if (dlugosc < 4 || dlugosc > 32) {
            lblHaslo.setText("Długość musi być z zakresu 4–32");
            return;
        }

        String pula = MALE;
        List<Character> znaki = new ArrayList<>();
        znaki.add(losowyZnak(MALE));
        if (chkDuze.isSelected()) { pula += DUZE; znaki.add(losowyZnak(DUZE)); }
        if (chkCyfry.isSelected()) { pula += CYFRY; znaki.add(losowyZnak(CYFRY)); }
        if (chkZnaki.isSelected()) { pula += ZNAKI; znaki.add(losowyZnak(ZNAKI)); }
        while (znaki.size() < dlugosc) znaki.add(losowyZnak(pula));

        Collections.shuffle(znaki, rnd);   // wymagane znaki w losowych miejscach
        StringBuilder sb = new StringBuilder();
        for (char c : znaki) sb.append(c);
        lblHaslo.setText(sb.toString());
    }
}

