package pl.inf04.hasla;

import android.os.Bundle;
import android.widget.Button;
import android.widget.CheckBox;
import android.widget.EditText;
import android.widget.TextView;
import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import java.util.Random;
import androidx.appcompat.app.AppCompatActivity;

public class MainActivity extends AppCompatActivity {

    private static final String MALE = "abcdefghijklmnopqrstuvwxyz";
    private static final String DUZE = "ABCDEFGHIJKLMNOPQRSTUVWXYZ";
    private static final String CYFRY = "0123456789";
    private static final String ZNAKI = "!@#$%&*";
    private final Random rnd = new Random();

    private char losowyZnak(String pula) {
        return pula.charAt(rnd.nextInt(pula.length()));
    }

    @Override
    protected void onCreate(Bundle savedInstanceState) {
        super.onCreate(savedInstanceState);
        setContentView(R.layout.activity_main);

        EditText etDlugosc = findViewById(R.id.etDlugosc);
        CheckBox cbDuze = findViewById(R.id.cbDuze);
        CheckBox cbCyfry = findViewById(R.id.cbCyfry);
        CheckBox cbZnaki = findViewById(R.id.cbZnaki);
        Button btnGeneruj = findViewById(R.id.btnGeneruj);
        TextView tvHaslo = findViewById(R.id.tvHaslo);

        btnGeneruj.setOnClickListener(v -> {

            String tekst = etDlugosc.getText().toString().trim();
            int dlugosc;
            try {
                dlugosc = Integer.parseInt(tekst);
            } catch (NumberFormatException e) {
                dlugosc = -1;
            }
            if (dlugosc < 4 || dlugosc > 32) {
                tvHaslo.setText("Długość musi być z zakresu 4–32");
                return;
            }

            String pula = MALE;
            List<Character> znaki = new ArrayList<>();
            znaki.add(losowyZnak(MALE));
            if (cbDuze.isChecked()) { pula += DUZE; znaki.add(losowyZnak(DUZE)); }
            if (cbCyfry.isChecked()) { pula += CYFRY; znaki.add(losowyZnak(CYFRY)); }
            if (cbZnaki.isChecked()) { pula += ZNAKI; znaki.add(losowyZnak(ZNAKI)); }
            while (znaki.size() < dlugosc) znaki.add(losowyZnak(pula));

            Collections.shuffle(znaki, rnd);   // wymagane znaki w losowych miejscach
            StringBuilder sb = new StringBuilder();
            for (char c : znaki) sb.append(c);
            tvHaslo.setText(sb.toString());
        });
    }
}

