package pl.inf04.hasla

import android.os.Bundle
import android.widget.Button
import android.widget.CheckBox
import android.widget.EditText
import android.widget.TextView
import androidx.appcompat.app.AppCompatActivity

class MainActivity : AppCompatActivity() {

    override fun onCreate(savedInstanceState: Bundle?) {
        super.onCreate(savedInstanceState)
        setContentView(R.layout.activity_main)

        val etDlugosc = findViewById<EditText>(R.id.etDlugosc)
        val cbDuze = findViewById<CheckBox>(R.id.cbDuze)
        val cbCyfry = findViewById<CheckBox>(R.id.cbCyfry)
        val cbZnaki = findViewById<CheckBox>(R.id.cbZnaki)
        val btnGeneruj = findViewById<Button>(R.id.btnGeneruj)
        val tvHaslo = findViewById<TextView>(R.id.tvHaslo)

        btnGeneruj.setOnClickListener {
            val dlugosc = etDlugosc.text.toString().trim().toIntOrNull()
            if (dlugosc == null || dlugosc !in 4..32) {
                tvHaslo.text = "Długość musi być z zakresu 4–32"
                return@setOnClickListener
            }

            var pula = MALE
            val znaki = mutableListOf(MALE.random())
            if (cbDuze.isChecked) { pula += DUZE; znaki.add(DUZE.random()) }
            if (cbCyfry.isChecked) { pula += CYFRY; znaki.add(CYFRY.random()) }
            if (cbZnaki.isChecked) { pula += ZNAKI; znaki.add(ZNAKI.random()) }
            while (znaki.size < dlugosc) znaki.add(pula.random())

            znaki.shuffle()   // wymagane znaki w losowych miejscach
            tvHaslo.text = znaki.joinToString("")
        }
    }

    companion object {
        const val MALE = "abcdefghijklmnopqrstuvwxyz"
        const val DUZE = "ABCDEFGHIJKLMNOPQRSTUVWXYZ"
        const val CYFRY = "0123456789"
        const val ZNAKI = "!@#$%&*"
    }
}
